\title{Manifold-Constrained Kruskal Rank Bounds on Dichotomy Counts}
\author{Aristotle}
\date{2026-07-02}

\begin{document}
\maketitle

\begin{abstract}
We study the expressive capacity of linear classifiers acting on data drawn from
low-dimensional structures. The classical measure of this capacity is
\emph{Cover's counting function}, $C(N,d)=2\sum_{k=0}^{d-1}\binom{N-1}{k}$, which
counts the homogeneously linearly-separable dichotomies of $N$ points in general
position in a $d$-parameter space. We develop the combinatorial theory of this
function from first principles, proving its defining one-point (Pascal)
recurrence, its saturation to $2^N$ when the parameter budget dominates the sample
($N\le d$), and its strict collapse below $2^N$ once the sample exceeds the budget
($d<N$). The analytic core is a \emph{maximal-solution theorem}: any nonnegative
integer quantity obeying Cover's base values and the subadditive one-point
recursion is bounded above by $C(N,d)$. We then apply this to geometry. For a
$d$-dimensional submanifold $E\subset\R^M$ and a smooth injective feature map
$\Phi:E\to\R^{M'}$, points of $E$ in general position have Kruskal rank $s\le d+1$,
and the $\Phi$-separable dichotomy count $C_F(N)$ obeys the same recursion with
effective parameter budget $p=d+M'+1$. Consequently $C_F(N)\le C(N,\,d+M'+1)$, and
strictly below $2^N$ whenever $p<N$. The bound depends only on the \emph{intrinsic}
dimension $d$ of the data manifold and the feature dimension $M'$---never on the
ambient dimension $M$.
\end{abstract}

\section{Introduction}

A homogeneous linear classifier on $\R^d$ partitions a finite point set into two
labeled classes by the sign of a linear functional. Given $N$ points, a
\emph{dichotomy} is an assignment of the two labels to the points; a dichotomy is
\emph{linearly separable} if some homogeneous hyperplane realizes it. The number
of separable dichotomies is the fundamental measure of a classifier family's
expressive power.

Cover (1965) answered this counting question for points in general position, and
the answer---Cover's counting function---has become a cornerstone of statistical
learning theory. Its two regimes encode a phase transition: below a critical
sample size the classifier realizes \emph{every} labeling; above it, some
labelings become permanently unreachable.

Modern data concentrates on low-dimensional manifolds. We ask how Cover's theory
transfers to that setting and answer precisely: the governing quantity is the
\emph{intrinsic} dimension of the data manifold, mediated by the \emph{Kruskal
rank} of the point configuration, and the ambient dimension is irrelevant.

Our contributions are: (1) a self-contained combinatorial development of Cover's
function; (2) a maximal-solution theorem characterizing it as the largest solution
of a subadditive one-point recursion; (3) the manifold-constrained dichotomy
bound.

\section{Definitions}

Throughout, $N$ denotes a sample size and $d$ a parameter (dimension) budget, both
positive integers unless stated otherwise.

\begin{definition}[Cover's counting function]
For $N,d\in\N$,
\[
C(N,d)\;=\;2\sum_{k=0}^{d-1}\binom{N-1}{k},
\]
the number of homogeneously linearly-separable dichotomies of $N$ points in
general position in a $d$-parameter space.
\end{definition}

\begin{definition}[General position]
A finite set $F$ of $N$ points in a $d$-parameter space is in \emph{general
position} if every subset of size at most $d$ is linearly independent. This is the
genericity condition under which Cover's count is exact.
\end{definition}

\begin{definition}[Kruskal rank]
The \emph{Kruskal rank} $s$ of a finite point configuration is the largest integer
such that every subset of $s$ points is linearly independent.
\end{definition}

\begin{definition}[Dichotomy system]\label{def:ds}
A function $g:\N\times\N\to\N$ is a \emph{dichotomy system} if, for the relevant
positive arguments,
\begin{itemize}
  \item base at one point: $g(1,d)\le 2$ for all $d\ge 1$;
  \item base in one dimension: $g(N,1)\le 2$ for all $N\ge 1$;
  \item one-point recursion: $g(N+1,d+1)\le g(N,d+1)+g(N,d)$ for all $N,d\ge 1$.
\end{itemize}
\end{definition}

\section{The combinatorial theory of Cover's function}

\begin{proposition}[Single point]
For $d\ge 1$, $C(1,d)=2$.
\end{proposition}
\begin{proof}
With $N=1$ the factors are $\binom{0}{k}$, vanishing for $k\ge 1$ and equal to $1$
for $k=0$. The sum collapses to its $k=0$ term, giving $C(1,d)=2$.
\end{proof}

\begin{proposition}[One parameter]
For all $N$, $C(N,1)=2$.
\end{proposition}
\begin{proof}
The sum $\sum_{k=0}^{0}\binom{N-1}{k}$ has the single term $\binom{N-1}{0}=1$.
\end{proof}

\begin{lemma}[Partial Pascal identity]\label{lem:pascal}
For all $m,d\in\N$,
\[
\sum_{k=0}^{d}\binom{m+1}{k}=\sum_{k=0}^{d}\binom{m}{k}+\sum_{k=0}^{d-1}\binom{m}{k}.
\]
\end{lemma}
\begin{proof}
Induct on $d$. The base $d=0$ reads $\binom{m+1}{0}=\binom{m}{0}$. For the step,
peel off the top term of each sum and apply Pascal's rule
$\binom{m+1}{d+1}=\binom{m}{d}+\binom{m}{d+1}$; the remaining sums are handled by
the inductive hypothesis.
\end{proof}

\begin{lemma}[Saturated partial sum]\label{lem:sat}
If $n<d$ then $\sum_{k=0}^{d-1}\binom{n}{k}=2^n$.
\end{lemma}
\begin{proof}
Once $d-1\ge n$, all nonzero terms are included and extra terms vanish; the full
sum is $2^n$ by the binomial theorem.
\end{proof}

\begin{lemma}[Partial sum bound]\label{lem:bound}
For all $n,d$, $\sum_{k=0}^{d-1}\binom{n}{k}\le 2^n$.
\end{lemma}
\begin{proof}
A partial sum of nonnegative terms is at most the completed sum, which equals
$2^n$ by Lemma~\ref{lem:sat}.
\end{proof}

\begin{theorem}[Cover / Pascal recurrence]\label{thm:rec}
For $N\ge 1$ and any $d$, $C(N+1,d+1)=C(N,d+1)+C(N,d)$.
\end{theorem}
\begin{proof}
Write $N=m+1$. Substituting the partial Pascal identity
(Lemma~\ref{lem:pascal}) with parameters $m$ and $d$ and multiplying by $2$ yields
the claim.
\end{proof}

\begin{theorem}[Global bound]
For $N\ge 1$ and any $d$, $C(N,d)\le 2^N$.
\end{theorem}
\begin{proof}
By Lemma~\ref{lem:bound} the inner sum is at most $2^{N-1}$, so
$C(N,d)\le 2\cdot 2^{N-1}=2^N$.
\end{proof}

\begin{theorem}[Saturation]
If $1\le N\le d$ then $C(N,d)=2^N$.
\end{theorem}
\begin{proof}
Here $N-1<d$, so Lemma~\ref{lem:sat} with $n=N-1$ gives inner sum $2^{N-1}$, and
doubling gives $2^N$.
\end{proof}

\begin{theorem}[Strict collapse]\label{thm:collapse}
If $d<N$ then $C(N,d)<2^N$.
\end{theorem}
\begin{proof}
The inner sum omits at least the top term $\binom{N-1}{N-1}=1$ from the full sum
$2^{N-1}$, so it is at most $2^{N-1}-1$ and $C(N,d)\le 2^N-2<2^N$.
\end{proof}

As a concrete instance, $C(5,3)=2(1+4+6)=22<32=2^5$.

\section{The maximal-solution theorem}

\begin{theorem}[Maximal solution]\label{thm:max}
Let $g:\N\times\N\to\N$ satisfy $g(1,d)\le 2$ for all $d\ge 1$, $g(N,1)\le 2$ for
all $N\ge 1$, and $g(N+1,d+1)\le g(N,d+1)+g(N,d)$ for all $N,d\ge 1$. Then
$g(N,d)\le C(N,d)$ for all $N,d\ge 1$.
\end{theorem}
\begin{proof}
Two-parameter induction: induct on $N$ starting at $N=1$, and within the step
case-split on $d$. For $N=1$, $g(1,d)\le 2=C(1,d)$. For $d=1$, $g(N,1)\le
2=C(N,1)$. For the step with $d=d'+1\ge 2$, apply the recursion for $g$, then the
inductive hypotheses $g(N,d'+1)\le C(N,d'+1)$ and $g(N,d')\le C(N,d')$, and finally
the Cover recurrence (Theorem~\ref{thm:rec}):
\[
g(N+1,d'+1)\le g(N,d'+1)+g(N,d')\le C(N,d'+1)+C(N,d')=C(N+1,d'+1).\qedhere
\]
\end{proof}

\begin{remark}[Tightness]
Cover's function itself satisfies all three hypotheses with equality, so the bound
of Theorem~\ref{thm:max} is attained and the class of dichotomy systems is
inhabited by a maximal element.
\end{remark}

\section{The manifold-constrained dichotomy bound}

\begin{proposition}[Rank ceiling on a manifold]\label{prop:rank}
Let $E\subset\R^M$ be a $d$-dimensional submanifold and $F\subset E$ an $N$-point
set in general position. Then the Kruskal rank $s$ of $F$, measured through any
smooth injective feature map $\Phi:E\to\R^{M'}$, satisfies $s\le d+1$.
\end{proposition}
\begin{proof}
Locally $E$ is parameterized by $d$ intrinsic coordinates; in homogeneous form at
most $d+1$ points can be linearly independent before the parameterization forces a
relation. A smooth injective $\Phi$ preserves distinctness and cannot increase the
general-position rank, so the ceiling transfers to feature space. The ambient
dimension $M$ plays no role.
\end{proof}

Combining a homogeneous separator in $\R^{M'}$ with the rank ceiling gives an
effective parameter budget $p=d+M'+1$, and the $\Phi$-separable dichotomy count
$C_F(N)$ is a dichotomy system (Definition~\ref{def:ds}) with parameter $p$.

\begin{theorem}[Manifold-constrained bound]\label{thm:mc}
With the notation above, $C_F(N)\le C(N,\,d+M'+1)$.
\end{theorem}
\begin{proof}
$C_F$ satisfies the base values and the one-point recursion with budget
$p=d+M'+1$, hence is a dichotomy system. Apply Theorem~\ref{thm:max} with $g=C_F$
and dimension argument $p$.
\end{proof}

\begin{theorem}[Expressivity collapse]
If $d+M'+1<N$ then $C_F(N)<2^N$.
\end{theorem}
\begin{proof}
Chain Theorem~\ref{thm:mc} with Theorem~\ref{thm:collapse} at budget
$p=d+M'+1<N$: $C_F(N)\le C(N,p)<2^N$.
\end{proof}

\begin{proposition}[Inhabitation and tightness]
The map $(N,d)\mapsto C(N,d)$ is itself a dichotomy system, satisfying every clause
of Definition~\ref{def:ds} with equality. Hence the abstraction is nonvacuous and
the bound $C_F(N)\le C(N,p)$ is best possible.
\end{proposition}

\section{Applications and discussion}

The fraction $C(N,d)/2^N$ is the proportion of labelings a homogeneous linear
classifier can realize; its transition from $1$ to near-$0$ as $N$ crosses $2d$ is
the classical capacity phase transition. Theorem~\ref{thm:mc} extends this to
feature-mapped classifiers on manifold data with $d\mapsto d+M'+1$. Because the
bound depends on $d$ and not $M$, the observed onset of expressivity collapse
serves as an operational probe of intrinsic dimension. The strict-collapse
threshold marks the boundary between the memorization regime and the constrained
regime that underpins generalization guarantees.

The unifying narrative is that expressive capacity is governed by intrinsic
geometry: the recursion is the geometry of adding a sample, the closed binomial
form is its combinatorial solution, and the maximal-solution theorem bridges the
two. The Kruskal rank ceiling $s\le d+1$ is the sole driver and is stable under
smooth injective maps, so the ambient dimension drops out entirely.

\section{Future directions}

\paragraph{Ambient-dimension irrelevance is exact.} For data on a fixed
$d$-dimensional structure embedded in ambient dimension $M$, we conjecture the
realizable labeling count is independent of $M$. The separating budget is set by
the general-position rank along the structure, capped by $d+1$ regardless of
embedding.

\paragraph{A phase transition sharp to a single sample.} We conjecture the fraction
of realizable labelings at fixed budget $p$ exhibits a threshold at $N=2p$:
essentially unity below and decaying to zero above, with transition width
independent of $p$.

\paragraph{Composition multiplies the rank penalty.} For a composition of two
smooth injective maps with intermediate dimensions $M'$ and $M''$, we conjecture
the effective budget is bounded by $\min(d+M'+1,\,d+M''+1)$---a bottleneck law in
which the least-expressive stage caps the pipeline.

