from math import comb

def cover_count(N: int, d: int) -> int:
    """Cover's counting function C(N, d) = 2 * sum_{k<d} binom(N-1, k)."""
    return 2 * sum(comb(N - 1, k) for k in range(d))

if __name__ == "__main__":
    for N in range(1, 9):
        row = [cover_count(N, d) for d in range(1, 7)]
        print(f"N={N}: {row}  (2^N = {2**N})")
    print("C(5,3) =", cover_count(5, 3), "< 2^5 =", 2**5)

from math import comb

def cover_count(N: int, d: int) -> int:
    return 2 * sum(comb(N - 1, k) for k in range(d))

def verify_regimes(max_N: int = 12, max_d: int = 8) -> None:
    rec = all(cover_count(N+1, d+1) == cover_count(N, d+1) + cover_count(N, d)
              for N in range(1, max_N) for d in range(max_d))
    sat = all(cover_count(N, d) == 2**N
              for N in range(1, max_N) for d in range(N, max_d + max_N))
    col = all(cover_count(N, d) < 2**N
              for N in range(2, max_N) for d in range(1, N))
    print("one-point recurrence:", rec)
    print("saturation (N<=d):   ", sat)
    print("strict collapse (d<N):", col)

if __name__ == "__main__":
    verify_regimes()

