function DOMINATED_BY_COVER(g, maxN, maxD):
    if exists d in [1,maxD] with g(1,d) > 2: return false
    if exists N in [1,maxN] with g(N,1) > 2: return false
    for N in [1,maxN-1], d in [1,maxD-1]:
        if g(N+1,d+1) > g(N,d+1) + g(N,d): return false
    for N in [1,maxN], d in [1,maxD]:
        if g(N,d) > COVER_COUNT(N,d): return false
    return true

